package estate.svc;

import estate.api.Context;
import estate.api.Service;
import estate.api.ServiceException;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

/** Notifier: sends marketing offers queued by the customer service. A "send" is a row in `sent`. */
public class Main implements Service {
    private Context ctx;
    private Connection db;

    @Override
    public void start(Context c) throws Exception {
        this.ctx = c;
        this.db = c.db();
        try (Statement s = db.createStatement()) {
            s.execute("CREATE TABLE IF NOT EXISTS sent(id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id VARCHAR(40) NOT NULL, "
                    + "offer_id VARCHAR(40) NOT NULL, ts BIGINT NOT NULL)");
            // The drop total is cumulative; sent_count is a small coordination cache for
            // instances of the new version. The sent table remains the source of truth for
            // sends, including rows written by an older version during a rollout.
            s.execute("CREATE TABLE IF NOT EXISTS offer_caps(customer_id VARCHAR(40) NOT NULL, offer_day BIGINT NOT NULL, "
                    + "sent_count INT NOT NULL, dropped_count BIGINT NOT NULL, PRIMARY KEY(customer_id, offer_day))");
        }
    }

    @Override
    public void onEvent(String topic, Map<String, String> ev) throws Exception {
        if (!"offer.queued".equals(topic)) return;
        String customerId = ev.get("customerId");
        long now = ctx.now();
        long day = Math.floorDiv(now, 100);
        long dayStart = day * 100;
        long nextDay = (day + 1) * 100;

        boolean oldAutoCommit = db.getAutoCommit();
        db.setAutoCommit(false);
        try {
            // MERGE makes the migration safe to run repeatedly on every instance.
            try (PreparedStatement merge = db.prepareStatement(
                    "MERGE INTO offer_caps(customer_id, offer_day, sent_count, dropped_count) "
                            + "KEY(customer_id, offer_day) VALUES (?, ?, 0, 0)")) {
                merge.setString(1, customerId);
                merge.setLong(2, day);
                merge.executeUpdate();
            }

            long dropped;
            int cachedSent;
            try (PreparedStatement q = db.prepareStatement(
                    "SELECT sent_count, dropped_count FROM offer_caps WHERE customer_id = ? AND offer_day = ? FOR UPDATE")) {
                q.setString(1, customerId);
                q.setLong(2, day);
                try (ResultSet rs = q.executeQuery()) {
                    rs.next();
                    cachedSent = rs.getInt(1);
                    dropped = rs.getLong(2);
                }
            }

            int actualSent;
            try (PreparedStatement q = db.prepareStatement(
                    "SELECT COUNT(*) FROM sent WHERE customer_id = ? AND ts >= ? AND ts < ?")) {
                q.setString(1, customerId);
                q.setLong(2, dayStart);
                q.setLong(3, nextDay);
                try (ResultSet rs = q.executeQuery()) {
                    rs.next();
                    actualSent = rs.getInt(1);
                }
            }
            int sent = Math.max(cachedSent, actualSent);
            if (sent < 2) {
                try (PreparedStatement ins = db.prepareStatement(
                        "INSERT INTO sent(customer_id, offer_id, ts) VALUES (?,?,?)")) {
                    ins.setString(1, customerId);
                    ins.setString(2, ev.get("offerId"));
                    ins.setLong(3, now);
                    ins.executeUpdate();
                }
                updateCap(customerId, day, sent + 1, dropped);
            } else {
                updateCap(customerId, day, sent, dropped + 1);
            }
            db.commit();
        } catch (Exception e) {
            db.rollback();
            throw e;
        } finally {
            db.setAutoCommit(oldAutoCommit);
        }
    }

    private void updateCap(String customerId, long day, int sent, long dropped) throws Exception {
        try (PreparedStatement u = db.prepareStatement(
                "UPDATE offer_caps SET sent_count = ?, dropped_count = ? WHERE customer_id = ? AND offer_day = ?")) {
            u.setInt(1, sent);
            u.setLong(2, dropped);
            u.setString(3, customerId);
            u.setLong(4, day);
            u.executeUpdate();
        }
    }

    @Override
    public Map<String, String> handle(String op, Map<String, String> req) throws ServiceException {
        try {
            switch (op) {
                case "health": {
                    try (Statement s = db.createStatement(); ResultSet rs = s.executeQuery("SELECT COUNT(*) FROM sent")) { rs.next(); }
                    return Map.of("status", "UP");
                }
                case "sent": return sent(req);
                default: throw new ServiceException("error", "unknown op " + op);
            }
        } catch (ServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new ServiceException("error", String.valueOf(e.getMessage()));
        }
    }

    /** Messages sent to a customer: count, ticks, and cumulative daily-cap drops. */
    private Map<String, String> sent(Map<String, String> req) throws Exception {
        try (PreparedStatement q = db.prepareStatement("SELECT ts FROM sent WHERE customer_id = ? ORDER BY id")) {
            q.setString(1, req.get("customerId"));
            StringBuilder ticks = new StringBuilder();
            int n = 0;
            try (ResultSet rs = q.executeQuery()) {
                while (rs.next()) { if (n++ > 0) ticks.append(','); ticks.append(rs.getLong(1)); }
            }
            try (PreparedStatement qd = db.prepareStatement(
                    "SELECT COALESCE(SUM(dropped_count), 0) FROM offer_caps WHERE customer_id = ?")) {
                qd.setString(1, req.get("customerId"));
                try (ResultSet rs = qd.executeQuery()) {
                    rs.next();
                    return Map.of("count", String.valueOf(n), "ticks", ticks.toString(),
                            "capped", String.valueOf(rs.getLong(1)));
                }
            }
        }
    }
}
